#include <bits/stdc++.h>using namespace std;#define int long longint T,n; void O_o(){    cin >> n;    auto ask = [&](vector<int> &s) -> int {// ask for a set        cout << '?' << ' ' << s.size();        for(auto &x : s){            cout << ' ' << x;        }        cout << endl;         int got;cin >> got;        return got;    };    auto pre = [&](int p) -> int {// ask how many ans in [1,pre]        if(p == 0){            return 0;        }        if(p == 2 * n + 1){            return 3;        }        vector<int> l,r;        for(int i=1;i<=p;i++){            l.push_back(i);        }        for(int i=p + 1;i<=n * 2 + 1;i++){            r.push_back(i);        }        int x = ask(l),y = ask(r);         if(x != y){            if(x > y){                return 1;            }else{                return 2;            }        }         int S = l.size();        if((S - x) & 1){            return 3;        }else{            return 0;        }    };    vector<int> ans;    for(int i=1;i<=3;i++){        int l = 0,r = 2 * n + 2;        int mid;        while(l + 1 != r){            mid = l + r >> 1;            int cnt = pre(mid);            if(cnt < i){                l = mid;            }else{                r = mid;            }        }        ans.push_back(r);    }    cout << '!' << ' ';    for(int x : ans){        cout << ' ' << x;    }    cout << endl;} signed main(){    ios::sync_with_stdio(false);    cin.tie(nullptr);cout.tie(nullptr);    cin >> T;    while(T--)O_o();    return 0;}